from collections import Counter
from html import unescape
from itertools import permutations
from pathlib import Path
from statistics import median
import json
import math
import re
import unicodedata

import numpy as np
from scipy.sparse import csr_matrix
from sklearn.utils.extmath import randomized_svd
from threadpoolctl import threadpool_limits

BASE = Path(__file__).parent
GROUPS = {
    2: [(7, 12), (8, 11), (9, 10)],
    3: [(14, 18), (15, 17)],
    4: [(19, 24), (20, 23), (21, 22)],
    5: [(25, 32), (26, 31), (27, 30), (28, 29)],
    6: [(33, 40), (34, 39), (35, 38), (36, 37)],
    7: [(41, 48), (42, 47), (43, 46), (44, 45)],
    8: [(49, 56), (50, 55), (51, 54), (52, 53)],
    9: [(57, 64), (58, 63), (59, 62), (60, 61)],
    10: [(65, 72), (66, 71), (67, 70), (68, 69)],
    11: [(73, 78), (74, 77), (75, 76)],
    12: [(80, 87), (81, 86), (82, 85), (83, 84)],
}
STOP = set("""a ab ac ad an ante apud atque autem cum de dum e enim ergo et ex iam in inter ita nam ne nec neque
non nunc per post pro propter quam quae que qui quia quod quo sed si sicut sine sub super tamen ut vel""".split())
TRANSCRIPTION = re.compile(
    r'<div class="transcription">\s*<h2>Transcription</h2>(.*?)</div>', re.S,
)

def tokenize(page):
    found = TRANSCRIPTION.search(page)
    if not found:
        return []
    text = unescape(re.sub(r'<[^>]+>', ' ', found[1]))
    text = re.sub(r'\[[^\]]*\]', ' ', text)
    text = re.sub(r'(?<=[^\W\d_])\\(?=[^\W\d_])', '', text)
    text = text.replace('\\', ' ').casefold()
    text = ''.join(c for c in unicodedata.normalize('NFKD', text)
                   if not unicodedata.combining(c))
    return re.findall(r'[a-z]+', text)

pages = {}
missing = {}
for folio in range(1, 95):
    for side in 'rv':
        page = f'{folio}{side}'
        file = BASE / 'pages' / f'{page}.html'
        if file.exists():
            words = tokenize(file.read_text())
            if words:
                pages[page] = words
            else:
                missing[page] = 'blank or no published transcription'
        else:
            missing[page] = 'capture unavailable'

all_words = [word for words in pages.values() for word in words]
blocks = [all_words[i:i + 40] for i in range(0, len(all_words) - 39, 40)]
document_counts = Counter(word for doc in blocks for word in set(doc) if word not in STOP)
vocabulary = {word: i for i, word in enumerate(sorted(w for w, df in document_counts.items() if df >= 2))}

def count_matrix(documents):
    data, row_indices, columns = [], [], []
    for row, words in enumerate(documents):
        for word, count in Counter(words).items():
            if word in vocabulary:
                row_indices.append(row)
                columns.append(vocabulary[word])
                data.append(float(count))
    return csr_matrix((data, (row_indices, columns)), shape=(len(documents), len(vocabulary)))

counts = count_matrix(blocks)
weights = {
    'tfidf': np.array([1 + math.log((1 + len(blocks)) / (1 + document_counts[w])) for w in vocabulary]),
}
fractions = counts.multiply(1 / np.maximum(np.asarray(counts.sum(axis=0)).ravel(), 1))
fraction_log = fractions.copy()
fraction_log.data = np.log(fraction_log.data)
weights['logentropy'] = 1 + np.asarray(fractions.multiply(fraction_log).sum(axis=0)).ravel() / math.log(len(blocks))

def weighted(mat, mode):
    mat = mat.copy()
    if mode == 'logentropy':
        mat.data = np.log1p(mat.data)
    return mat.multiply(weights[mode]).tocsr()

def cosine_matrix(first, last):
    first /= np.maximum(np.linalg.norm(first, axis=1), 1e-20)[:, None]
    last /= np.maximum(np.linalg.norm(last, axis=1), 1e-20)[:, None]
    return last @ first.T

def plan_rank(ref, candidates, score, vector_edges):
    reference = score(ref)
    results = [(r, score(r)) for r in candidates]
    values = [value for _, value in results]
    maximum = max(values)
    best = [r for r, value in results if abs(value - maximum) < 1e-10]
    target_edges = set(vector_edges(ref))
    overlap = max(len(target_edges & set(vector_edges(order))) for order in best)
    return {
        'ref': list(ref), 'n_orders': len(results),
        'better_count': sum(value > reference + 1e-10 for value in values),
        'ties_with_ref': sum(abs(value - reference) < 1e-10 for value in values),
        'optima': len(best), 'first_maximizer': list(best[0]),
        'min': min(values), 'mean': float(np.mean(values)), 'median': median(values),
        'ref_score': reference, 'max': maximum,
        'best_directional_edges_recovered': overlap, 'edge_total': len(target_edges),
    }

labels = list(pages)
by_label = {name: i for i, name in enumerate(labels)}

def analyze(similarity):
    def pair(a, b):
        return float(similarity[by_label[f'{a}v'], by_label[f'{b}r']])

    result = {'physical_nested': {}, 'true_contiguous_blocks': {}, 'limitations': {}}
    for q, sheets in GROUPS.items():
        need = [f'{n}{rv}' for pair in sheets for n in pair for rv in 'rv']
        absent = [x for x in need if x not in by_label]
        if absent:
            result['limitations'][q] = absent
            continue

        def nested_edges(order):
            leaves = [sheets[i][0] for i in order] + [sheets[i][1] for i in reversed(order)]
            return list(zip(leaves, leaves[1:]))

        def rank_pairs(edges):
            return sum(pair(a, b) for a, b in edges) / len(edges)

        ref = tuple(range(len(sheets)))
        orders = list(permutations(ref))
        result['physical_nested'][q] = plan_rank(
            ref, orders, lambda order: rank_pairs(nested_edges(order)), nested_edges,
        )

        if q in range(5, 11):
            real_leaves = sorted(n for sheet in sheets for n in sheet)
            assert len(real_leaves) == 8 and real_leaves[-1] - real_leaves[0] == 7
            blocks = list(zip(real_leaves[::2], real_leaves[1::2]))

            def stack_edges(order):
                return [(blocks[a][1], blocks[b][0]) for a, b in zip(order, order[1:])]

            result['true_contiguous_blocks'][q] = plan_rank(
                ref, orders, lambda order: rank_pairs(stack_edges(order)), stack_edges,
            )
    return result

whole = count_matrix([pages[page] for page in labels])
head = count_matrix([pages[page][:40] for page in labels])
tail = count_matrix([pages[page][-40:] for page in labels])
experiments = {}
with threadpool_limits(limits=2):
    for mode in ('tfidf', 'logentropy'):
        _, _, basis = randomized_svd(weighted(counts, mode), n_components=75, n_iter=12, random_state=408)
        w = weighted(whole, mode) @ basis.T
        experiments[f'{mode}_75_page'] = analyze(cosine_matrix(w.copy(), w.copy()))
        if mode == 'tfidf':
            a, b = weighted(head, mode) @ basis.T, weighted(tail, mode) @ basis.T
            experiments['tfidf_75_edges'] = analyze(cosine_matrix(a, b))
            weighted_pages = weighted(whole, mode).toarray()
            experiments['tfidf_direct_page'] = analyze(cosine_matrix(weighted_pages.copy(), weighted_pages.copy()))

result = {
    'word_count': len(all_words), 'word_counts_by_page': {k:len(v) for k,v in pages.items()},
    'training_block_count': len(blocks), 'vocabulary': len(vocabulary),
    'unavailable_or_blank': missing, 'lexical_trials': experiments,
}
(BASE / 'calibration.json').write_text(json.dumps(result,indent=2)+'\n')
print(len(pages),len(all_words),len(blocks),len(vocabulary))

