from collections import Counter
import json
import math
from statistics import median

import numpy as np
from scipy.sparse import csr_matrix
from sklearn.utils.extmath import randomized_svd
from threadpoolctl import threadpool_limits

from calibrate import BASE, GROUPS, STOP, analyze, cosine_matrix, labels, pages

def fold_from(training_labels):
    blocks = []
    for label in training_labels:
        words = pages[label]
        for i in range(0, len(words), 40):
            chunk = words[i:i+40]
            if len(chunk) >= 20:
                blocks.append(chunk)
    df = Counter(word for doc in blocks for word in set(doc) if word not in STOP)
    vocab = {word: i for i, word in enumerate(sorted(w for w, n in df.items() if n >= 2))}
    idf = np.array([1 + math.log((1 + len(blocks)) / (1 + df[w])) for w in vocab])

    def mat(docs):
        data, rows, cols = [], [], []
        for row, words in enumerate(docs):
            for word, count in Counter(words).items():
                if word in vocab:
                    rows.append(row)
                    cols.append(vocab[word])
                    data.append(count * idf[vocab[word]])
        return csr_matrix((data, (rows, cols)), shape=(len(docs), len(vocab)))

    train = mat(blocks)
    allpages = mat([pages[label] for label in labels])
    _, _, basis = randomized_svd(train, n_components=75, n_iter=12, random_state=408)
    folded = allpages @ basis.T
    coverage = {
        label: (sum(word in vocab for word in pages[label]), len(pages[label]))
        for label in labels
    }
    return analyze(cosine_matrix(folded.copy(), folded.copy())), len(blocks), len(vocab), coverage

with threadpool_limits(limits=2):
    aligned, nblocks, nterms, aligned_coverage = fold_from(labels)
    strict = {"physical_nested": {}, "true_contiguous_blocks": {}, "fit_sizes": {}}
    for q, sheets in GROUPS.items():
        if q not in aligned["physical_nested"]:
            continue
        minimum = min(n for pair in sheets for n in pair)
        maximum = max(n for pair in sheets for n in pair)
        fit_labels = [lab for lab in labels if not minimum <= int(lab[:-1]) <= maximum]
        results, n, vocab, coverage = fold_from(fit_labels)
        faces = [f"{leaf}{side}" for pair in sheets for leaf in pair for side in "rv"]
        def admitted_share(table):
            return sum(table[lab][0] for lab in faces) / sum(table[lab][1] for lab in faces)
        strict["fit_sizes"][q] = {
            "blocks": n, "vocabulary": vocab,
            "test_token_coverage_by_aligned_training": admitted_share(aligned_coverage),
            "test_token_coverage_when_quire_excluded": admitted_share(coverage),
        }
        strict["physical_nested"][q] = results["physical_nested"][q]
        if q in results["true_contiguous_blocks"]:
            strict["true_contiguous_blocks"][q] = results["true_contiguous_blocks"][q]

out = {"page_aligned": aligned, "training_aligned": {"blocks": nblocks, "vocabulary": nterms},
       "whole_quire_excluded": strict}
(BASE / 'sensitivity.json').write_text(json.dumps(out, indent=2) + '\n')
